"use client";

import { type RefObject, useEffect } from "react";

/** Text of the nearest heading before `el` in document order (h1 to h4). */
export function precedingHeading(el: Element): string {
	let node: Element | null = el;
	for (let hops = 0; node && hops < 40; hops++) {
		let sib = node.previousElementSibling;
		while (sib) {
			const inner = sib.querySelectorAll("h1,h2,h3,h4");
			const h = sib.matches("h1,h2,h3,h4") ? sib : inner[inner.length - 1];
			if (h?.textContent?.trim()) return h.textContent.trim();
			sib = sib.previousElementSibling;
		}
		node = node.parentElement;
	}
	return "";
}

/** `base`, or `base (2)`, `base (3)` when another region on the page already has it. */
export function uniqueRegionName(el: Element, base: string): string {
	const taken = new Set(
		[...document.querySelectorAll("[role=region][aria-label]")]
			.filter((r) => r !== el)
			.map((r) => r.getAttribute("aria-label")),
	);
	if (!taken.has(base)) return base;
	let n = 2;
	while (taken.has(`${base} (${n})`)) n++;
	return `${base} (${n})`;
}

/**
 * Names a scrollable region after mount. Every docs table and code block was
 * a region with the same name (or none), which axe reports as
 * landmark-unique and a screen reader lists as a row of identical landmarks.
 */
export function useRegionName(ref: RefObject<HTMLElement | null>, describe: (el: HTMLElement) => string) {
	useEffect(() => {
		const el = ref.current;
		if (!el) return;
		const base = describe(el).replace(/\s+/g, " ").trim();
		if (base) el.setAttribute("aria-label", uniqueRegionName(el, base.length > 80 ? `${base.slice(0, 77)}...` : base));
	}, [ref, describe]);
}
